const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '拔塞过程：u = x/h 的三个阶段' },
      { kind: 'text', payload: '瓶口基准线保持水平，位移按真实比例（示意）' },
      { kind: 'text', payload: 'u = 0' },
      { kind: 'text', payload: 'x = 0' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: '底部距瓶口 h' },
      { kind: 'text', payload: 'u = 1/2' },
      { kind: 'text', payload: 'x = h/2' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: '底部距瓶口 h/2' },
      { kind: 'text', payload: 'u = 1' },
      { kind: 'text', payload: 'x = h' },
      { kind: 'text', payload: '底部到达瓶口' },
      { kind: 'text', payload: '瓶口基准线' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var S = Math.min(W / 960, H / 600);
    if (!(S > 0)) { S = 1; }
    var OX = (W - 960 * S) / 2;
    var OY = (H - 600 * S) / 2;

    function px(x) { return OX + x * S; }
    function py(y) { return OY + y * S; }
    function lineC(x0, y0, x1, y1) {
      return [['M', px(x0), py(y0)], ['L', px(x1), py(y1)]];
    }
    function rectC(x0, y0, x1, y1) {
      return [['M', px(x0), py(y0)], ['L', px(x1), py(y0)], ['L', px(x1), py(y1)], ['L', px(x0), py(y1)], ['Z']];
    }
    function cid(k) { return metrics[k].contentId; }

    var baseY = 276;
    var hLen = 150;
    var corkLen = 0.7 * hLen;
    var neckHalf = 60;
    var wallT = 12;
    var corkHalf = 44;
    var neckBottom = baseY + 216;
    var y0 = baseY + hLen;
    var centers = [160, 480, 800];
    var bottoms = [y0, baseY + hLen / 2, baseY];

    var paths = [];
    var nodes = [];

    paths.push({ id: 'bg', commands: [['M', 0, 0], ['L', W, 0], ['L', W, H], ['L', 0, H], ['Z']] });
    nodes.push({ type: 'path', pathId: 'bg', fill: '#ffffff' });

    for (var i = 0; i < 3; i++) {
      var cx = centers[i];
      var bottom = bottoms[i];
      var top = bottom - corkLen;

      paths.push({ id: 'base' + i, commands: lineC(cx - 136, baseY, cx + 136, baseY) });
      nodes.push({ type: 'path', pathId: 'base' + i, fill: '#c0392b', stroke: { width: 1.6 * S, cap: 'butt', dash: [7 * S, 6 * S] } });

      var walls = rectC(cx - neckHalf, baseY, cx - neckHalf + wallT, neckBottom)
        .concat(rectC(cx + neckHalf - wallT, baseY, cx + neckHalf, neckBottom));
      paths.push({ id: 'neck' + i, commands: walls });
      nodes.push({ type: 'path', pathId: 'neck' + i, fill: '#dfe7ee', stroke: { width: 1.6 * S, join: 'round' } });

      paths.push({ id: 'cut' + i, commands: lineC(cx - neckHalf, neckBottom, cx + neckHalf, neckBottom) });
      nodes.push({ type: 'path', pathId: 'cut' + i, fill: '#95a6b8', stroke: { width: 1.4 * S, dash: [5 * S, 5 * S] } });

      paths.push({ id: 'cork' + i, commands: rectC(cx - corkHalf, top, cx + corkHalf, bottom) });
      nodes.push({ type: 'path', pathId: 'cork' + i, fill: '#e6bb8c', stroke: { width: 1.8 * S, join: 'round' } });

      if (i < 2) {
        var dimX = cx - 76;
        var dimCmds = lineC(dimX, baseY, dimX, bottom)
          .concat(lineC(dimX - 7, baseY, dimX + 7, baseY))
          .concat(lineC(dimX - 7, bottom, dimX + 7, bottom));
        paths.push({ id: 'dim' + i, commands: dimCmds });
        nodes.push({ type: 'path', pathId: 'dim' + i, fill: '#2a3b4d', stroke: { width: 1.4 * S, cap: 'butt' } });
      }

      var ax = cx + 76;
      var dCmds = lineC(ax - 14, y0, ax, y0);
      if (i > 0) {
        dCmds = dCmds.concat(lineC(ax, y0, ax, bottom));
        dCmds.push(['M', px(ax - 6), py(bottom + 10)]);
        dCmds.push(['L', px(ax), py(bottom)]);
        dCmds.push(['L', px(ax + 6), py(bottom + 10)]);
      }
      paths.push({ id: 'disp' + i, commands: dCmds });
      nodes.push({ type: 'path', pathId: 'disp' + i, fill: '#2b6cb0', stroke: { width: 1.8 * S, cap: 'round' } });
    }

    var uIdx = [2, 6, 10];
    var xIdx = [3, 7, 11];
    var depIdx = [4, 8];
    var capIdx = [5, 9, 12];

    for (var j = 0; j < 3; j++) {
      var cxj = centers[j];
      var bj = bottoms[j];

      nodes.push({ type: 'label', contentId: cid(uIdx[j]), anchor: { x: px(cxj), y: py(520) }, hAlign: 'center', vAlign: 'middle', color: '#1b2a3a' });
      nodes.push({ type: 'label', contentId: cid(capIdx[j]), anchor: { x: px(cxj), y: py(550) }, hAlign: 'center', vAlign: 'middle', color: '#4a5a6b' });

      var xLabelY = (j === 0) ? y0 : (y0 + bj) / 2;
      nodes.push({ type: 'label', contentId: cid(xIdx[j]), anchor: { x: px(cxj + 88), y: py(xLabelY) }, hAlign: 'left', vAlign: 'middle', color: '#2b6cb0' });

      if (j < 2) {
        nodes.push({ type: 'label', contentId: cid(depIdx[j]), anchor: { x: px(cxj - 84), y: py((baseY + bj) / 2) }, hAlign: 'right', vAlign: 'middle', color: '#2a3b4d' });
      }
    }

    nodes.push({ type: 'label', contentId: cid(0), anchor: { x: px(480), y: py(34) }, hAlign: 'center', vAlign: 'middle', color: '#1b2a3a' });
    nodes.push({ type: 'label', contentId: cid(1), anchor: { x: px(480), y: py(66) }, hAlign: 'center', vAlign: 'middle', color: '#4a5a6b' });
    nodes.push({ type: 'label', contentId: cid(13), anchor: { x: px(24), y: py(268) }, hAlign: 'left', vAlign: 'bottom', color: '#c0392b' });

    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
